S2 = {
"APP_TAGLINE": ["Untangle the arrows, one by one", "얽힌 화살표를 하나씩 빼내세요", "Entwirre die Pfeile, einen nach dem anderen", "Desenreda las flechas una a una", "Démêlez les flèches une à une", "からまった矢印をひとつずつ抜こう", "فكّ تشابك الأسهم واحدًا تلو الآخر", "一根一根解开缠绕的箭头", "一根一根解開纏繞的箭頭"],
"COACH_TAP": ["Tap an arrow. It slides out the way its head points.", "화살표를 탭하면 머리 방향으로 스르륵 빠져나가요.", "Tippe einen Pfeil. Er gleitet in Kopfrichtung hinaus.", "Toca una flecha. Sale deslizándose hacia donde apunta.", "Touchez une flèche : elle glisse dans le sens de sa pointe.", "矢印をタップすると、頭の向きへスルッと抜けます。", "انقر سهمًا فينزلق خارجًا باتجاه رأسه.", "点按箭头，它会朝箭头方向滑出去。", "點按箭頭，它會朝箭頭方向滑出去。"],
"COACH_OPEN": ["The long arrow in the middle is in the way. Free it first.", "가운데 긴 화살표가 길을 막고 있어요. 먼저 빼 보세요.", "Der lange Pfeil in der Mitte steht im Weg. Zieh ihn zuerst heraus.", "La flecha larga del centro estorba. Sácala primero.", "La longue flèche du milieu gêne. Retirez-la d'abord.", "真ん中の長い矢印が道をふさいでいます。先に抜こう。", "السهم الطويل في الوسط يسد الطريق. أخرجه أولًا.", "中间那根长箭头挡住了路，先把它移走。", "中間那根長箭頭擋住了路，先把它移走。"],
"COACH_LOOK": ["Look ahead of each head: the way must be clear to the edge.", "머리 앞이 판 끝까지 비어 있어야 빠질 수 있어요.", "Schau vor jeden Kopf: Der Weg muss bis zum Rand frei sein.", "Mira delante de cada punta: el camino debe estar libre hasta el borde.", "Regardez devant chaque pointe : la voie doit être libre jusqu'au bord.", "頭の先が端まで空いていれば抜けられます。", "انظر أمام كل رأس: يجب أن يكون الطريق خاليًا حتى الحافة.", "看看箭头前方：一直到边缘都要空着。", "看看箭頭前方：一直到邊緣都要空著。"],
"COACH_HEARTS": ["From here, tapping a blocked arrow costs a heart.", "이제부터 막힌 화살표를 누르면 하트가 하나 줄어요.", "Ab jetzt kostet ein blockierter Pfeil ein Herz.", "Desde aquí, tocar una flecha bloqueada cuesta un corazón.", "Désormais, toucher une flèche bloquée coûte un cœur.", "ここからは、ふさがった矢印を押すとハートが1つ減ります。", "من الآن، النقر على سهم محجوب يكلف قلبًا.", "从现在起，点被挡住的箭头会扣一颗心。", "從現在起，點被擋住的箭頭會扣一顆心。"],
"COACH_CHAIN": ["Each arrow you free opens a new way. Keep going!", "하나를 빼면 막혔던 길이 열려요. 이어서 빼 보세요!", "Jeder befreite Pfeil öffnet einen neuen Weg. Weiter!", "Cada flecha que sacas abre un camino nuevo. ¡Sigue!", "Chaque flèche retirée ouvre un nouveau chemin. Continuez !", "1本抜くと新しい道が開きます。続けて抜こう！", "كل سهم تُخرجه يفتح طريقًا جديدًا. واصل!", "每移走一根，就会打开新的路。继续！", "每移走一根，就會打開新的路。繼續！"],
"COACH_BLOCKED": ["Blocked! Find an arrow with a clear way ahead.", "막혔어요! 머리 앞이 비어 있는 화살표를 찾아보세요.", "Blockiert! Such einen Pfeil mit freiem Weg.", "¡Bloqueada! Busca una flecha con el camino libre.", "Bloquée ! Cherchez une flèche au chemin libre.", "ふさがっています！頭の先が空いた矢印を探そう。", "محجوب! ابحث عن سهم طريقه أمامه خالٍ.", "被挡住了！找前方空着的箭头。", "被擋住了！找前方空著的箭頭。"],
"FAIL_REASON_ARROWS": ["You tapped blocked arrows three times. An arrow only leaves when the way ahead of its head is clear to the edge.", "막힌 화살표를 3번 눌렀어요. 머리 앞이 판 끝까지 비어 있는 화살표만 빠져나가요.", "Du hast dreimal blockierte Pfeile getippt. Ein Pfeil kommt nur hinaus, wenn der Weg vor seinem Kopf bis zum Rand frei ist.", "Tocaste tres veces flechas bloqueadas. Una flecha solo sale si el camino ante su punta está libre hasta el borde.", "Vous avez touché trois fois des flèches bloquées. Une flèche ne sort que si la voie devant sa pointe est libre jusqu'au bord.", "ふさがった矢印を3回押しました。頭の先が端まで空いている矢印だけが抜けられます。", "نقرت أسهمًا محجوبة ثلاث مرات. لا يخرج السهم إلا إذا كان الطريق أمام رأسه خاليًا حتى الحافة.", "你点了三次被挡住的箭头。只有箭头前方一直到边缘都空着时才能滑出。", "你點了三次被擋住的箭頭。只有箭頭前方一直到邊緣都空著時才能滑出。"],
"CLEAR_STATS_ARROWS": ["%d arrows · %d mistakes", "화살표 %d개 · 실수 %d번", "%d Pfeile · %d Fehler", "%d flechas · %d errores", "%d flèches · %d erreurs", "矢印 %d · ミス %d", "%d أسهم · %d أخطاء", "%d 根箭头 · 失误 %d 次", "%d 根箭頭 · 失誤 %d 次"],
"CHAPTER1_DONE_BODY": ["You finished every stage so far. New stages are on the way.", "지금까지의 스테이지를 모두 깼어요. 새 스테이지를 준비하고 있어요.", "Du hast alle bisherigen Level geschafft. Neue folgen.", "Superaste todos los niveles disponibles. Llegarán más.", "Vous avez terminé tous les niveaux disponibles. D'autres arrivent.", "今あるステージをすべてクリアしました。新しいステージを準備中です。", "أنهيت كل المراحل المتاحة. مراحل جديدة في الطريق.", "已通过目前所有关卡，新关卡正在准备中。", "已通過目前所有關卡，新關卡正在準備中。"],
"ZOOM_IN": ["Zoom in", "확대", "Vergrößern", "Acercar", "Zoomer", "拡大", "تكبير", "放大", "放大"],
"RETRY": ["Retry", "재도전", "Nochmal", "Reintentar", "Réessayer", "再挑戦", "إعادة المحاولة", "再试一次", "再試一次"],
"RETRY_CAPTION": ["Out of hearts · try again", "하트를 모두 썼어요 · 다시 도전해요", "Keine Herzen mehr · nochmal versuchen", "Sin corazones · inténtalo otra vez", "Plus de cœurs · réessayez", "ハートがなくなりました・もう一度挑戦", "نفدت القلوب · حاول مجددًا", "爱心用完了 · 再试一次", "愛心用完了 · 再試一次"],
"CHECKPOINT_RESTORE": ["Back to checkpoint (free)", "체크포인트부터 다시 (무료)", "Ab Checkpoint (gratis)", "Desde el punto de control (gratis)", "Depuis le point de contrôle (gratuit)", "チェックポイントから (無料)", "من نقطة الحفظ (مجانًا)", "从检查点继续（免费）", "從檢查點繼續（免費）"],
"CHECKPOINT_LEFT": ["%d arrows left there", "남은 화살표 %d개부터 시작해요", "Dort sind noch %d Pfeile übrig", "Allí quedan %d flechas", "Il y reste %d flèches", "残り %d 本から始まります", "يتبقى هناك %d سهمًا", "从剩下的 %d 个箭头开始", "從剩下的 %d 個箭頭開始"],
"CHECKPOINT_SAVED": ["Checkpoint! Half the arrows are out. If you run out of hearts, you can come back here.", "체크포인트! 화살표 절반을 뺐어요. 하트를 다 써도 여기서 다시 할 수 있어요.", "Checkpoint! Die Hälfte ist draußen. Gehen die Herzen aus, geht es hier weiter.", "¡Punto de control! Ya salió la mitad. Si te quedas sin corazones, vuelves aquí.", "Point de contrôle ! La moitié est sortie. Sans cœurs, vous reprendrez ici.", "チェックポイント！半分を外しました。ハートがなくなってもここから再開できます。", "نقطة حفظ! خرج نصف الأسهم. إن نفدت القلوب ستعود من هنا.", "检查点！已移出一半箭头。爱心用完也能从这里继续。", "檢查點！已移出一半箭頭。愛心用完也能從這裡繼續。"],
"CHECKPOINT_BACK": ["Back at the checkpoint with full hearts.", "체크포인트로 돌아왔어요. 하트가 가득 찼어요.", "Zurück am Checkpoint, alle Herzen voll.", "De vuelta en el punto de control con todos los corazones.", "De retour au point de contrôle, cœurs pleins.", "チェックポイントに戻りました。ハートは満タンです。", "عدت إلى نقطة الحفظ بقلوب كاملة.", "已回到检查点，爱心已满。", "已回到檢查點，愛心已滿。"],
"BLOCK_WARNING": ["Blocked! The purple arrow is in the way of your red one. This first one is free: no heart lost.", "막혔어요! 보라 화살표가 빨간 화살표의 앞을 막고 있어요. 이번 한 번은 하트가 줄지 않아요.", "Blockiert! Der lila Pfeil steht deinem roten im Weg. Dieses erste Mal kostet kein Herz.", "¡Bloqueada! La flecha morada estorba a tu flecha roja. Esta primera vez no pierdes corazón.", "Bloquée ! La flèche violette gêne votre flèche rouge. Cette première fois ne coûte pas de cœur.", "ふさがっています！紫の矢印が赤い矢印の前をふさいでいます。今回だけハートは減りません。", "مسدود! السهم البنفسجي يعترض سهمك الأحمر. هذه المرة الأولى بلا خسارة قلب.", "被挡住了！紫色箭头挡住了红色箭头的路。这次不扣爱心。", "被擋住了！紫色箭頭擋住了紅色箭頭的路。這次不扣愛心。"],
"COACH_CAMERA": ["Drag to look around, pinch to zoom. The corner button shows the whole board.", "끌어서 둘러보고, 두 손가락으로 확대·축소해요. 구석 버튼을 누르면 판 전체가 보여요.", "Ziehen zum Umsehen, mit zwei Fingern zoomen. Die Ecktaste zeigt das ganze Brett.", "Arrastra para mirar y pellizca para hacer zoom. El botón de la esquina muestra todo.", "Glissez pour explorer, pincez pour zoomer. Le bouton du coin montre tout le plateau.", "ドラッグで見回し、2本指で拡大・縮小。隅のボタンで全体を表示します。", "اسحب للتجول وقرّب بإصبعين. زر الزاوية يعرض اللوحة كاملة.", "拖动查看，双指缩放。角落按钮可查看整个盘面。", "拖動查看，雙指縮放。角落按鈕可查看整個盤面。"],
"BIG_CLEAR": ["Big board cleared!", "큰 판 클리어!", "Großes Brett geschafft!", "¡Tablero grande superado!", "Grand plateau réussi !", "大きな盤面クリア！", "اكتملت اللوحة الكبيرة!", "大关卡完成！", "大關卡完成！"],
"STORY_READ": ["Read the story", "이야기 보기", "Geschichte lesen", "Leer la historia", "Lire l'histoire", "ストーリーを読む", "اقرأ القصة", "阅读故事", "閱讀故事"],
"FIT_BOARD": ["Fit board", "판 전체 보기", "Ganzes Brett", "Ver todo", "Plateau entier", "全体を表示", "عرض اللوحة كاملة", "查看全盘", "查看全盤"],
"MIGRATION_NOTICE": ["Outtap has new arrow puzzles. Your journey starts again from stage 1.", "아웃탭이 새로운 화살표 퍼즐로 바뀌었어요. 스테이지 1부터 다시 시작해요.", "Outtap hat neue Pfeilrätsel. Es geht wieder bei Level 1 los.", "Outtap tiene nuevos puzles de flechas. Empiezas de nuevo en el nivel 1.", "Outtap propose de nouveaux puzzles de flèches. Vous repartez du niveau 1.", "アウトタップが新しい矢印パズルになりました。ステージ1から始まります。", "أصبح لـ Outtap ألغاز أسهم جديدة. تبدأ رحلتك من المرحلة 1.", "Outtap 换上了全新的箭头谜题，从第 1 关重新开始。", "Outtap 換上了全新的箭頭謎題，從第 1 關重新開始。"],
}
