def parse(path):
    entries = {}
    header = ""
    text = path.read_text()
    blocks = text.split("\n\n")
    header = blocks[0]
    for block in blocks[1:]:
        mid = re.search(r'^msgid "(.*)"$', block, re.M)
        mstr = re.search(r'^msgstr "(.*)"$', block, re.M)
        if mid and mstr:
            entries[mid.group(1)] = mstr.group(1)
    return header, entries


def esc(value):
    # A literal "\\n" in a source string stays a PO newline escape.
    return value.replace("\\", "\\\\").replace('"', '\\"').replace("\\\\n", "\\n")


for index, lang in enumerate(LANGS):
    path = ROOT / "localization" / f"{lang}.po"
    header, entries = parse(path)
    for key, values in S.items():
        entries[key] = esc(values[index])
    body = "\n\n".join(f'msgid "{k}"\nmsgstr "{v}"' for k, v in entries.items())
    path.write_text(header.rstrip() + "\n\n" + body + "\n")
print(f"Updated {len(LANGS)} locales with {len(S)} keys")
